package com.gymtrackerpro.app;
import android.app.*;import android.content.*;import androidx.core.app.NotificationCompat;
public class RecoveryReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){String name=i.getStringExtra("name");String channel="recovery";NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(android.os.Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel(channel,"Recupero",NotificationManager.IMPORTANCE_HIGH));Notification x=new NotificationCompat.Builder(c,channel).setSmallIcon(R.drawable.app_icon).setContentTitle("Recupero terminato").setContentText(name==null?"Puoi ripartire con la prossima serie.":"Puoi ripartire: "+name).setAutoCancel(true).build();n.notify((int)System.currentTimeMillis(),x);}}
